-- ============================================================ -- Notify Tools -- Production Database Schema -- Compatible with MySQL 8+ -- Charset: utf8mb4 -- Designed for Hostinger shared hosting -- ============================================================ SET NAMES utf8mb4; SET time_zone = '+05:30'; -- ------------------------------------------------------------ -- IMPORTANT -- ------------------------------------------------------------ -- 1. Do NOT store plain-text passwords. -- 2. Admin passwords must be generated in PHP using: -- password_hash($password, PASSWORD_DEFAULT) -- 3. Login verification must use: -- password_verify($password, $passwordHash) -- 4. No default admin account is inserted by this SQL file. -- ------------------------------------------------------------ -- ============================================================ -- TABLE: admins -- Stores authorized administrative users only. -- ============================================================ CREATE TABLE IF NOT EXISTS `admins` ( `id` BIGINT UNSIGNED NOT NULL AUTO_INCREMENT, `name` VARCHAR(120) NOT NULL, `email` VARCHAR(190) NOT NULL, `password_hash` VARCHAR(255) NOT NULL, `role` ENUM('super_admin', 'admin', 'editor') NOT NULL DEFAULT 'admin', `status` ENUM('active', 'inactive', 'suspended') NOT NULL DEFAULT 'active', `last_login` DATETIME NULL DEFAULT NULL, `created_at` TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, `updated_at` TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, PRIMARY KEY (`id`), UNIQUE KEY `uq_admins_email` (`email`), KEY `idx_admins_role` (`role`), KEY `idx_admins_status` (`status`), KEY `idx_admins_last_login` (`last_login`) ) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci; -- ============================================================ -- TABLE: categories -- Groups tools into logical sections. -- Examples: Student Tools, Finance Tools, Government Job Tools. -- ============================================================ CREATE TABLE IF NOT EXISTS `categories` ( `id` BIGINT UNSIGNED NOT NULL AUTO_INCREMENT, `name` VARCHAR(120) NOT NULL, `slug` VARCHAR(150) NOT NULL, `icon` VARCHAR(255) NULL DEFAULT NULL, `description` TEXT NULL, `sort_order` INT UNSIGNED NOT NULL DEFAULT 0, `status` ENUM('active', 'inactive') NOT NULL DEFAULT 'active', `created_at` TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, `updated_at` TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, PRIMARY KEY (`id`), UNIQUE KEY `uq_categories_slug` (`slug`), KEY `idx_categories_name` (`name`), KEY `idx_categories_status` (`status`), KEY `idx_categories_sort_order` (`sort_order`), KEY `idx_categories_status_sort` (`status`, `sort_order`) ) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci; -- ============================================================ -- TABLE: tools -- Stores tool metadata and SEO information. -- -- IMPORTANT: -- tool_type should store a safe registered module identifier -- such as: -- age-calculator -- percentage-calculator -- emi-calculator -- -- PHP executable code should NOT be stored in this table. -- -- custom_css and custom_js are provided for controlled trusted -- admin customization. They should only be rendered after proper -- authorization and sanitization in the application. -- ============================================================ CREATE TABLE IF NOT EXISTS `tools` ( `id` BIGINT UNSIGNED NOT NULL AUTO_INCREMENT, `category_id` BIGINT UNSIGNED NULL DEFAULT NULL, `name` VARCHAR(160) NOT NULL, `slug` VARCHAR(180) NOT NULL, `icon` VARCHAR(255) NULL DEFAULT NULL, `short_description` VARCHAR(500) NULL DEFAULT NULL, `full_description` LONGTEXT NULL, `tool_type` VARCHAR(120) NOT NULL, `featured` TINYINT(1) NOT NULL DEFAULT 0, `popular` TINYINT(1) NOT NULL DEFAULT 0, `status` ENUM('draft', 'published', 'inactive') NOT NULL DEFAULT 'draft', `seo_title` VARCHAR(255) NULL DEFAULT NULL, `meta_description` VARCHAR(500) NULL DEFAULT NULL, `custom_css` MEDIUMTEXT NULL, `custom_js` MEDIUMTEXT NULL, `created_at` TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, `updated_at` TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, PRIMARY KEY (`id`), UNIQUE KEY `uq_tools_slug` (`slug`), KEY `idx_tools_category_id` (`category_id`), KEY `idx_tools_name` (`name`), KEY `idx_tools_tool_type` (`tool_type`), KEY `idx_tools_status` (`status`), KEY `idx_tools_featured` (`featured`), KEY `idx_tools_popular` (`popular`), KEY `idx_tools_created_at` (`created_at`), KEY `idx_tools_updated_at` (`updated_at`), KEY `idx_tools_public_listing` (`status`, `featured`, `popular`, `updated_at`), CONSTRAINT `fk_tools_category` FOREIGN KEY (`category_id`) REFERENCES `categories` (`id`) ON UPDATE CASCADE ON DELETE SET NULL ) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci; -- ============================================================ -- TABLE: pages -- Stores editable static pages. -- Examples: -- About Us -- Contact Us -- Privacy Policy -- Terms & Conditions -- Disclaimer -- ============================================================ CREATE TABLE IF NOT EXISTS `pages` ( `id` BIGINT UNSIGNED NOT NULL AUTO_INCREMENT, `title` VARCHAR(180) NOT NULL, `slug` VARCHAR(190) NOT NULL, `content` LONGTEXT NULL, `seo_title` VARCHAR(255) NULL DEFAULT NULL, `meta_description` VARCHAR(500) NULL DEFAULT NULL, `status` ENUM('draft', 'published', 'inactive') NOT NULL DEFAULT 'draft', `updated_at` TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, PRIMARY KEY (`id`), UNIQUE KEY `uq_pages_slug` (`slug`), KEY `idx_pages_title` (`title`), KEY `idx_pages_status` (`status`) ) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci; -- ============================================================ -- TABLE: settings -- Key/value storage for global website configuration. -- ============================================================ CREATE TABLE IF NOT EXISTS `settings` ( `setting_key` VARCHAR(150) NOT NULL, `setting_value` LONGTEXT NULL, PRIMARY KEY (`setting_key`) ) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci; -- ============================================================ -- TABLE: ads -- Stores trusted advertisement snippets and placements. -- -- Only authenticated trusted admins should be allowed to modify -- ad_code. -- ============================================================ CREATE TABLE IF NOT EXISTS `ads` ( `id` BIGINT UNSIGNED NOT NULL AUTO_INCREMENT, `name` VARCHAR(150) NOT NULL, `placement` VARCHAR(100) NOT NULL, `ad_code` LONGTEXT NULL, `status` ENUM('active', 'inactive') NOT NULL DEFAULT 'inactive', PRIMARY KEY (`id`), UNIQUE KEY `uq_ads_placement` (`placement`), KEY `idx_ads_status` (`status`) ) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci; -- ============================================================ -- TABLE: announcements -- Controls optional announcement bars or notices. -- ============================================================ CREATE TABLE IF NOT EXISTS `announcements` ( `id` BIGINT UNSIGNED NOT NULL AUTO_INCREMENT, `message` VARCHAR(500) NOT NULL, `link` VARCHAR(2048) NULL DEFAULT NULL, `status` ENUM('active', 'inactive') NOT NULL DEFAULT 'inactive', `start_at` DATETIME NULL DEFAULT NULL, `end_at` DATETIME NULL DEFAULT NULL, PRIMARY KEY (`id`), KEY `idx_announcements_status` (`status`), KEY `idx_announcements_start_at` (`start_at`), KEY `idx_announcements_end_at` (`end_at`), KEY `idx_announcements_active_period` (`status`, `start_at`, `end_at`) ) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci; -- ============================================================ -- TABLE: audit_logs -- Records important administrative actions. -- -- Audit records intentionally remain if an admin is deleted. -- admin_id therefore becomes NULL using ON DELETE SET NULL. -- ============================================================ CREATE TABLE IF NOT EXISTS `audit_logs` ( `id` BIGINT UNSIGNED NOT NULL AUTO_INCREMENT, `admin_id` BIGINT UNSIGNED NULL DEFAULT NULL, `action` VARCHAR(150) NOT NULL, `entity_type` VARCHAR(100) NULL DEFAULT NULL, `entity_id` BIGINT UNSIGNED NULL DEFAULT NULL, `ip_address` VARCHAR(45) NULL DEFAULT NULL, `user_agent` VARCHAR(500) NULL DEFAULT NULL, `created_at` TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, PRIMARY KEY (`id`), KEY `idx_audit_admin_id` (`admin_id`), KEY `idx_audit_action` (`action`), KEY `idx_audit_entity` (`entity_type`, `entity_id`), KEY `idx_audit_created_at` (`created_at`), CONSTRAINT `fk_audit_admin` FOREIGN KEY (`admin_id`) REFERENCES `admins` (`id`) ON UPDATE CASCADE ON DELETE SET NULL ) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci; -- ============================================================ -- TABLE: login_attempts -- Used for admin login rate limiting and security monitoring. -- -- Old login attempts should periodically be deleted by PHP -- or a scheduled cron job. -- ============================================================ CREATE TABLE IF NOT EXISTS `login_attempts` ( `id` BIGINT UNSIGNED NOT NULL AUTO_INCREMENT, `email` VARCHAR(190) NULL DEFAULT NULL, `ip_address` VARCHAR(45) NOT NULL, `successful` TINYINT(1) NOT NULL DEFAULT 0, `attempted_at` TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, PRIMARY KEY (`id`), KEY `idx_login_email` (`email`), KEY `idx_login_ip` (`ip_address`), KEY `idx_login_attempted_at` (`attempted_at`), KEY `idx_login_successful` (`successful`), KEY `idx_login_rate_limit_ip` (`ip_address`, `attempted_at`), KEY `idx_login_rate_limit_email` (`email`, `attempted_at`) ) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci; -- ============================================================ -- DEFAULT CATEGORIES -- Safe starter categories for Notify Tools. -- INSERT IGNORE prevents duplicate insertion if this SQL is run -- more than once. -- ============================================================ INSERT IGNORE INTO `categories` ( `name`, `slug`, `icon`, `description`, `sort_order`, `status` ) VALUES ( 'Student & Exam Tools', 'student-exam-tools', 'graduation-cap', 'Useful calculators and utilities for students and competitive exam aspirants.', 10, 'active' ), ( 'Government Job Tools', 'government-job-tools', 'briefcase', 'Age, eligibility, qualification and deadline tools for government job applicants.', 20, 'active' ), ( 'Salary & Employee Tools', 'salary-employee-tools', 'wallet', 'Salary, DA, HRA, NPS and employee-related calculators.', 30, 'active' ), ( 'Finance Tools', 'finance-tools', 'calculator', 'EMI, interest, GST, discount, profit and personal finance calculators.', 40, 'active' ), ( 'Text Tools', 'text-tools', 'file-text', 'Word counting, character counting, case conversion and other text utilities.', 50, 'active' ), ( 'PDF Tools', 'pdf-tools', 'file', 'Browser-based PDF utilities designed with privacy and simplicity in mind.', 60, 'active' ), ( 'Image Tools', 'image-tools', 'image', 'Image compression, resizing, conversion and other useful image utilities.', 70, 'active' ), ( 'Security & Generator Tools', 'security-generator-tools', 'shield', 'Privacy-friendly password, UUID and random data generators.', 80, 'active' ), ( 'Date & Time Tools', 'date-time-tools', 'calendar', 'Age, date difference, countdown and time-related calculators.', 90, 'active' ); -- ============================================================ -- DEFAULT STATIC PAGES -- Content can be added later through /admin. -- ============================================================ INSERT IGNORE INTO `pages` ( `title`, `slug`, `content`, `seo_title`, `meta_description`, `status` ) VALUES ( 'About Us', 'about', '', 'About Notify Tools', 'Learn more about Notify Tools and our free online calculators and utilities.', 'published' ), ( 'Contact Us', 'contact', '', 'Contact Notify Tools', 'Contact the Notify Tools team.', 'published' ), ( 'Privacy Policy', 'privacy-policy', '', 'Privacy Policy - Notify Tools', 'Read the Notify Tools privacy policy and learn how information is handled.', 'published' ), ( 'Terms & Conditions', 'terms-and-conditions', '', 'Terms & Conditions - Notify Tools', 'Read the terms and conditions for using Notify Tools.', 'published' ), ( 'Disclaimer', 'disclaimer', '', 'Disclaimer - Notify Tools', 'Important disclaimer regarding the calculators and information available on Notify Tools.', 'published' ); -- ============================================================ -- DEFAULT GLOBAL SETTINGS -- These settings can later be managed from /admin/settings.php. -- ============================================================ INSERT IGNORE INTO `settings` (`setting_key`, `setting_value`) VALUES ('site_name', 'Notify Tools'), ('site_tagline', 'Free Online Tools for Everyday Tasks'), ('site_description', 'Fast, free and mobile-friendly online calculators and utility tools.'), ('site_url', ''), ('contact_email', ''), ('logo_path', '/assets/images/logo.png'), ('favicon_path', '/assets/icons/favicon.png'), ('primary_color', '#0B2C5F'), ('secondary_color', '#1D4ED8'), ('background_color', '#F7F9FC'), ('font_family', 'Poppins'), ('default_seo_title', 'Notify Tools - Free Online Calculators & Utility Tools'), ('default_meta_description', 'Use free online calculators and useful tools for students, job aspirants, employees and everyday tasks.'), ('whatsapp_url', ''), ('telegram_url', ''), ('youtube_url', ''), ('facebook_url', ''), ('instagram_url', ''), ('pwa_app_name', 'Notify Tools'), ('pwa_short_name', 'Notify Tools'), ('pwa_theme_color', '#0B2C5F'), ('pwa_background_color', '#FFFFFF'), ('maintenance_mode', '0'), ('analytics_code', ''), ('ads_enabled', '0'), ('site_search_enabled', '1'), ('dark_mode_enabled', '1'), ('pwa_enabled', '1'), ('timezone', 'Asia/Kolkata'); -- ============================================================ -- DEFAULT AD PLACEMENTS -- No advertisement code is included. -- These slots remain inactive until configured by an admin. -- ============================================================ INSERT IGNORE INTO `ads` ( `name`, `placement`, `ad_code`, `status` ) VALUES ( 'Homepage Top', 'homepage_top', '', 'inactive' ), ( 'Homepage Middle', 'homepage_middle', '', 'inactive' ), ( 'Tool Page Top', 'tool_top', '', 'inactive' ), ( 'Tool Result Area', 'tool_result', '', 'inactive' ), ( 'Tool Page Bottom', 'tool_bottom', '', 'inactive' ), ( 'Sidebar', 'sidebar', '', 'inactive' ), ( 'Footer Advertisement', 'footer', '', 'inactive' ); -- ============================================================ -- OPTIONAL STARTER TOOL RECORDS -- -- These records contain metadata only. -- The actual calculator logic should live in trusted PHP/JS -- modules inside the source repository. -- ============================================================ INSERT IGNORE INTO `tools` ( `category_id`, `name`, `slug`, `icon`, `short_description`, `full_description`, `tool_type`, `featured`, `popular`, `status`, `seo_title`, `meta_description` ) SELECT c.id, 'Age Calculator', 'age-calculator', 'cake', 'Calculate your exact age in years, months and days.', 'Use the Notify Tools Age Calculator to calculate your exact age quickly and accurately.', 'age-calculator', 1, 1, 'draft', 'Age Calculator - Calculate Your Exact Age', 'Calculate your exact age in years, months and days using the free Notify Tools Age Calculator.' FROM `categories` c WHERE c.slug = 'date-time-tools' LIMIT 1; INSERT IGNORE INTO `tools` ( `category_id`, `name`, `slug`, `icon`, `short_description`, `full_description`, `tool_type`, `featured`, `popular`, `status`, `seo_title`, `meta_description` ) SELECT c.id, 'Percentage Calculator', 'percentage-calculator', 'percent', 'Calculate percentages quickly and easily.', 'Use this free Percentage Calculator to calculate percentages for marks, values and everyday calculations.', 'percentage-calculator', 1, 1, 'draft', 'Percentage Calculator - Free Online Tool', 'Calculate percentages quickly with the free Notify Tools Percentage Calculator.' FROM `categories` c WHERE c.slug = 'student-exam-tools' LIMIT 1; INSERT IGNORE INTO `tools` ( `category_id`, `name`, `slug`, `icon`, `short_description`, `full_description`, `tool_type`, `featured`, `popular`, `status`, `seo_title`, `meta_description` ) SELECT c.id, 'EMI Calculator', 'emi-calculator', 'credit-card', 'Estimate monthly loan EMI, total payment and interest.', 'Use this free EMI Calculator to estimate monthly loan payments and total interest.', 'emi-calculator', 1, 1, 'draft', 'EMI Calculator - Calculate Monthly Loan EMI', 'Calculate estimated monthly loan EMI, total payment and interest with Notify Tools.' FROM `categories` c WHERE c.slug = 'finance-tools' LIMIT 1; -- ============================================================ -- SECURITY NOTES -- ============================================================ -- -- Create the first administrator through a secure PHP setup -- script rather than inserting a plain password here. -- -- Example PHP password generation: -- -- $hash = password_hash($password, PASSWORD_DEFAULT); -- -- Then store $hash in admins.password_hash. -- -- Never commit production database credentials or password -- hashes belonging to real administrators to a public GitHub -- repository. -- -- Recommended login-attempt cleanup: -- -- DELETE FROM login_attempts -- WHERE attempted_at < (NOW() - INTERVAL 30 DAY); -- -- Recommended audit-log retention depends on site requirements. -- ============================================================
